pub fn harbor_scene_reset(m: &mut dyn Mem, host: &mut dyn OpsHost, regs: [u32; 8]) -> [u32; 8] {
    let mut c = Cpu { r: regs, ..Cpu::default() };
    let mut pc: u32 = 0x613290;
    loop {
        match pc {
            0x613290 => {
            c.push(m,c.get(6,32));
            c.set(6,32,c.get(1,32));
            c.push(m,c.get(7,32));
            c.set(1,32,0x13ecu32);
            c.set(7,32,c.r[6].wrapping_add(0x2f3c));
            { let a = c.get(0,32); let r = c.or(a,0xffffffffu32,32); c.set(0,32,r); }
            c.stos(m,32,true);
            c.set(1,32,c.get(6,32));
            c.push(m, 0x6132ab);
            { let args = []; c.r[0] = host.call(m, 0x618f90, c.r[1], &args); }
            c.r[4] = c.r[4].wrapping_add(4);
            { let a = c.r[6].wrapping_add(0x5c); wm(m,a,16,0xffu32); }
            { let a = c.r[6].wrapping_add(0x7eec); wm(m,a,32,0x0u32); }
            { let v = c.pop(m); c.set(7,32,v); }
            { let v = c.pop(m); c.set(6,32,v); }
            c.r[4] = c.r[4].wrapping_add(4); return c.r;
            }
            _ => unreachable!("pc fuera de la función: {pc:#x}"),
        }
    }
}

